{
  "omisión de contenido tecnológico": {
    "definicion": "Consiste en excluir deliberadamente información sobre avances, productos o impactos de la tecnología en una pieza mediática, creando una visión parcial de la realidad que minimiza la presencia del sector tecnológico.",
    "ejemplo": "En varios informes de prensa de 2024 sobre la reforma educativa, se mencionó la modernización de la infraestructura pero se omitieron los nuevos sistemas de IA que la normativa exigirá a las escuelas.",
    "como_detectarla": [
      "1. Identificar el tema central y revisar fuentes originales o documentos oficiales que incluyan datos tecnológicos.",
      "2. Comparar la información publicada con esas fuentes para detectar ausencias de referencias a la tecnología.",
      "3. Analizar si la omisión altera la percepción del impacto o la complejidad del asunto tratado."
    ]
  },
  "framing de noticias locales y culturales": {
    "definicion": "Estrategia que presenta acontecimientos locales o culturales bajo un enfoque que resalta valores, tradiciones o identidades específicas, orientando la interpretación del público hacia una visión particular de la comunidad.",
    "ejemplo": "En marzo de 2024, un medio regional de Andalucía cubrió la Feria de Abril enfocándose en la preservación de la música flamenca, mientras relegó la discusión sobre el impacto económico de la feria para los pequeños comerciantes.",
    "como_detectarla": [
      "1. Detectar los elementos destacados (costumbres, símbolos) y los relegados (economía, política).",
      "2. Revisar si la selección de hechos enfatiza una narrativa de identidad cultural.",
      "3. Verificar la presencia de fuentes alternativas que ofrezcan una visión más equilibrada."
    ]
  },
  "omisión deliberada del tema de IA": {
    "definicion": "Práctica editorial que suprime de forma intencionada cualquier referencia a la inteligencia artificial en la cobertura de un asunto, a fin de evitar controversias, temores o debates sobre su influencia.",
    "ejemplo": "En un artículo de junio 2024 sobre la nueva ley de protección de datos en la UE, los analistas omitieron mencionar que la normativa incluye disposiciones específicas para sistemas de IA, pese a que el texto oficial lo destaca.",
    "como_detectarla": [
      "1. Consultar la legislación, informe o estudio original para identificar menciones a IA.",
      "2. Comparar esas menciones con la cobertura mediática y anotar ausencias.",
      "3. Evaluar si la ausencia de IA cambia la comprensión del alcance o la relevancia del tema."
    ]
  },
  "framing de conflicto político en lugar de tecnológico": {
    "definicion": "Redirección del foco informativo hacia disputas políticas, minimizando o ignorando los componentes tecnológicos que realmente impulsan o habilitan el conflicto, con el fin de simplificar la narrativa o polarizar a la audiencia.",
    "ejemplo": "Durante la crisis de suministro eléctrico en Texas (2024), varios portales priorizaron la rivalidad entre el gobernador y el Congreso federal, sin abordar cómo la falta de inversión en redes inteligentes y almacenamiento de energía exacerbó la situación.",
    "como_detectarla": [
      "1. Identificar los factores tecnológicos subyacentes al problema (infraestructura, software, hardware).",
      "2. Analizar la cobertura para ver si se centra exclusivamente en actores políticos.",
      "3. Contrastar con informes técnicos o académicos que destaquen la dimensión tecnológica."
    ]
  },
  "infotainment con énfasis en figuras públicas": {
    "definicion": "Formato mediático que combina información y entretenimiento, privilegiando la presencia de celebridades o políticos como protagonistas, a menudo reduciendo la profundidad del contenido factual a favor de la atracción del público.",
    "ejemplo": "En el programa nocturno de TV de octubre 2024, se explicó la reforma fiscal mediante una entrevista exclusiva con un famoso cantante, cuyo carisma sustituyó la exposición detallada de los cambios legislativos.",
    "como_detectarla": [
      "1. Observar si la pieza dedica más tiempo a la vida o opinión de la figura pública que a los datos del tema.",
      "2. Evaluar la calidad y cantidad de información factual presentada.",
      "3. Verificar si el estilo, música y efectos visuales buscan entretener más que informar."
    ]
  }
}
